import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new BufferedReader(new InputStreamReader(System.in)).readLine().trim();
        // Cut every time the L/R balance returns to zero.
        int balance = 0, answer = 0;
        for (int i = 0; i < s.length(); i++) {
            balance += s.charAt(i) == 'L' ? 1 : -1;
            if (balance == 0) answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	var s string
	fmt.Fscan(bufio.NewReaderSize(os.Stdin, 1<<20), &s)
	// Cut every time the L/R balance returns to zero.
	balance, answer := 0, 0
	for i := 0; i < len(s); i++ {
		if s[i] == 'L' {
			balance++
		} else {
			balance--
		}
		if balance == 0 {
			answer++
		}
	}
	fmt.Println(answer)
}
